parameters.jsCode:
// Parse Claude's JSON response
const raw = $input.first().json.content[0].text;
let parsed;
try {
  // Extract JSON from response (Claude sometimes adds explanation)
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch(e) {
  // Fallback if JSON parse fails
  parsed = {
    missions: [{
      rank: 1,
      task: 'Jarvis konnte nicht parsen – manuell priorisieren',
      pillar: 'System',
      why: 'JSON-Fehler: ' + e.message,
      tools: []
    }],
    daily_focus: 'Manuelle Priorisierung heute',
    alert: null
  };
}
return [{ json: parsed }];

